/** Back-office : finance_officer, super_admin, avec double authentification. */

export interface WalletAdminServiceClient {
  getHolderWallet(request: GetHolderWalletRequest, metadata?: Metadata): Observable<GetHolderWalletResponse>;

  listHolderStatement(
    request: ListHolderStatementRequest,
    metadata?: Metadata,
  ): Observable<ListHolderStatementResponse>;

  listWalletPayouts(request: ListWalletPayoutsRequest, metadata?: Metadata): Observable<ListWalletPayoutsResponse>;

  /** Soldes des comptes internes de KSP et total dû aux titulaires. */

  getLedgerOverview(request: GetLedgerOverviewRequest, metadata?: Metadata): Observable<GetLedgerOverviewResponse>;

  /**
   * Crédit manuel d'un portefeuille prépayé avec motif (ADR-046) : remboursement, ou recharge reçue
   * mais non créditée (écart de montant traité par la finance). Auteur gardé dans le grand livre.
   * Contrôles (ADR-048) : une recharge est vérifiée auprès de payment (paiement "wallet_top_up" du
   * même titulaire, réussi ou en écart de montant, montant au plus égal au montant reçu) ; un
   * remboursement est plafonné (WALLET_MANUAL_REFUND_MAX) et justifié (motif de 15 caractères au
   * moins). Au-delà de WALLET_CREDIT_APPROVAL_THRESHOLD, le crédit attend la validation d'un second
   * membre de la finance : rien n'est écrit, la demande est rendue dans pending_request.
   */

  creditPrepaidWallet(
    request: CreditPrepaidWalletRequest,
    metadata?: Metadata,
  ): Observable<CreditPrepaidWalletResponse>;

  /** Demandes de crédit manuel en attente de validation (ou validées), les plus récentes d'abord. */

  listManualCreditRequests(
    request: ListManualCreditRequestsRequest,
    metadata?: Metadata,
  ): Observable<ListManualCreditRequestsResponse>;

  /**
   * Validation par un second membre de la finance (jamais l'auteur de la demande) : le crédit est
   * écrit. Rejouable : une demande déjà validée rend son crédit.
   */

  approveManualCredit(
    request: ApproveManualCreditRequest,
    metadata?: Metadata,
  ): Observable<ApproveManualCreditResponse>;

  /**
   * Rejet d'une demande de crédit en attente, avec motif (recharge en espèces non retrouvée en
   * caisse…) ; l'auteur peut rejeter sa propre demande pour l'annuler (à valider). Rien n'est crédité.
   */

  rejectManualCredit(request: RejectManualCreditRequest, metadata?: Metadata): Observable<RejectManualCreditResponse>;

  /** Demandes de retrait (R-WL-04), les plus anciennes d'abord ; filtres facultatifs. */

  listWithdrawals(request: ListWithdrawalsRequest, metadata?: Metadata): Observable<ListWithdrawalsResponse>;

  /**
   * Premier membre de la finance : vérifications faites (titulaire, numéro), la demande attend la
   * validation d'une deuxième personne ("requested" → "awaiting_approval").
   */

  processWithdrawal(request: ProcessWithdrawalRequest, metadata?: Metadata): Observable<ProcessWithdrawalResponse>;

  /**
   * Deuxième personne de la finance (jamais celle qui a traité la demande) : le virement est
   * transmis à payment (PayoutService.RequestPayout, référence "wallet_withdrawal:<id>")
   * ("awaiting_approval" → "submitted"), puis soldé à payment.payout.completed ("completed") ou rendu
   * au portefeuille à payment.payout.failed ("failed"). Rejouable.
   */

  approveWithdrawal(request: ApproveWithdrawalRequest, metadata?: Metadata): Observable<ApproveWithdrawalResponse>;

  /**
   * Refus motivé d'une demande "requested" ou "awaiting_approval" : le montant retenu est rendu au
   * portefeuille ("rejected").
   */

  rejectWithdrawal(request: RejectWithdrawalRequest, metadata?: Metadata): Observable<RejectWithdrawalResponse>;
}

